 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = max((v for v in counts if v != background), key=lambda v: counts[v])

    motif_cells = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] not in (background, marker)]
    r0 = min(r for r, c in motif_cells)
    r1 = max(r for r, c in motif_cells)
    c0 = min(c for r, c in motif_cells)
    c1 = max(c for r, c in motif_cells)
    pattern = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    anchor_r, anchor_c = (r1 - r0) // 2, (c1 - c0) // 2

    out = [row[:] for row in grid]
    for mr in range(h):
        for mc in range(w):
            if grid[mr][mc] != marker:
                continue
            for pr, row in enumerate(pattern):
                for pc, value in enumerate(row):
                    rr, cc = mr + pr - anchor_r, mc + pc - anchor_c
                    if 0 <= rr < h and 0 <= cc < w and value != background:
                        out[rr][cc] = value
    return out


